;// ./shared/ui/cn.ts
function cn_cn(...args) {
    const out = [];
    for (const a of args) {
        if (!a)
            continue;
        if (typeof a === 'string' || typeof a === 'number') {
            out.push(String(a));
        }
        else if (typeof a === 'object') {
            for (const key in a) {
                if (a[key])
                    out.push(key);
            }
        }
    }
    return out.join(' ');
}

